+fn load_key() -> [u8; 32] {
+    let mut key = *DEFAULT_DEV_KEY;
+    if let Ok(value) = std::env::var("AGENTHUB_SECRET_KEY") {
+        let value = value.trim();
+        if !value.is_empty() {
+            let bytes = BASE64
+                .decode(value)
+                .unwrap_or_else(|_| value.as_bytes().to_vec());
+            if bytes.len() >= 32 {
+                key.copy_from_slice(&bytes[..32]);
+            } else {
+                key[..bytes.len()].copy_from_slice(&bytes);
+            }
