+func TestNativeRootfsExportEnabledParsesEnv(t *testing.T) {
+	t.Setenv("CUBEMASTER_NATIVE_ROOTFS_EXPORT_ENABLED", "")
+	if nativeRootfsExportEnabled() {
+		t.Fatal("expected native rootfs export to be disabled by default")
+	}
+
