+	if !nativeRootfsExportEnabled() {
+		t.Fatal("expected native rootfs export to be enabled")
+	}
+
+	t.Setenv("CUBEMASTER_NATIVE_ROOTFS_EXPORT_ENABLED", "not-a-bool")
